```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_rw};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => out.push(b as char),
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment lookup (approved grant); the result never affects the output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&published.date)
        );
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            for id in &published.considered {
                state_rw::put(id, "seen");
                recorded += 1;
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

Notes:
- The enrichment URL uses the digest's `date` as the query text, since `PublishedDigest` has no dedicated text field. The query is percent-encoded.
- I used `fetch` rather than `get`, so a transport failure is returned as a value and the output is unchanged.
- Ids are marked seen only when `published` is true. Otherwise `recorded` is 0.

